using UnityEngine;
namespace LunarRelay {
public static class DecorModels {
 static Material silver,dark,blue,leaf,soil,glow,earth;static Mesh leafMesh;
 static Material Mat(Color c,float smooth=.3f){var m=new Material(Shader.Find("Universal Render Pipeline/Lit"));m.color=c;m.SetFloat("_Smoothness",smooth);return m;}
 static void Init(){if(silver)return;silver=Mat(new Color(.48f,.53f,.55f));dark=Mat(new Color(.035f,.055f,.065f));blue=Mat(new Color(.12f,.32f,.43f));leaf=Mat(new Color(.13f,.38f,.23f));leaf.SetFloat("_Cull",0);soil=Mat(new Color(.055f,.045f,.035f));glow=Mat(new Color(.48f,.77f,.9f));glow.EnableKeyword("_EMISSION");glow.SetColor("_EmissionColor",new Color(.25f,.55f,.7f));earth=Mat(Color.white);earth.SetTexture("_BaseMap",EarthTexture());earth.EnableKeyword("_EMISSION");earth.SetTexture("_EmissionMap",earth.mainTexture);earth.SetColor("_EmissionColor",Color.white*.55f);}
 static void Part(Transform root,string name,Vector3 p,Vector3 size,Material mat,PrimitiveType type=PrimitiveType.Cube){var g=GameObject.CreatePrimitive(type);g.name=name;Object.DestroyImmediate(g.GetComponent<Collider>());g.transform.SetParent(root,false);g.transform.localPosition=p;g.transform.localScale=type==PrimitiveType.Capsule?new Vector3(size.x,size.y*.5f,size.z):size;if(type==PrimitiveType.Cube)RoundedForms.Soften(g,.16f);g.GetComponent<Renderer>().sharedMaterial=mat;}
 public static GameObject Create(int kind){Init();var root=new GameObject("Lunar decor "+kind);
 if(kind==0){Part(root.transform,"Weighted plinth",new Vector3(0,.025f,0),new Vector3(.22f,.05f,.18f),dark);Part(root.transform,"Silver shell",new Vector3(0,.052f,0),new Vector3(.19f,.04f,.15f),silver);Part(root.transform,"Curved light column",new Vector3(0,.19f,0),new Vector3(.055f,.25f,.055f),silver,PrimitiveType.Capsule);Part(root.transform,"Frosted lens",new Vector3(0,.28f,.012f),new Vector3(.16f,.11f,.10f),glow,PrimitiveType.Sphere);Part(root.transform,"Floating shade",new Vector3(0,.337f,0),new Vector3(.19f,.032f,.13f),dark);var light=new GameObject("Soft decor light").AddComponent<Light>();light.transform.SetParent(root.transform,false);light.transform.localPosition=new Vector3(0,.28f,.025f);light.type=LightType.Point;light.range=1.6f;light.intensity=.35f;light.color=new Color(.62f,.82f,1);light.shadows=LightShadows.None;}
 if(kind==1){Part(root.transform,"Graphite pot foot",new Vector3(0,.017f,0),new Vector3(.18f,.034f,.18f),dark);Part(root.transform,"Moulded grey planter",new Vector3(0,.087f,0),new Vector3(.20f,.14f,.20f),silver);Part(root.transform,"Soil bed",new Vector3(0,.16f,0),new Vector3(.165f,.012f,.165f),soil);Part(root.transform,"Irrigation indicator",new Vector3(0,.065f,.102f),new Vector3(.07f,.009f,.006f),glow);
 for(int j=0;j<9;j++){var g=new GameObject("Sculpted leaf");g.transform.SetParent(root.transform,false);g.transform.localPosition=new Vector3(0,.16f,0);g.transform.localRotation=Quaternion.Euler(0,j*137.5f,0);var vs=new System.Collections.Generic.List<Vector3>();var ix=new System.Collections.Generic.List<int>();float len=.14f+(j%3)*.035f;for(int k=0;k<=8;k++){float t=k/8f,w=Mathf.Sin(t*Mathf.PI)*.033f;vs.Add(new Vector3(-w,.16f*Mathf.Sin(t*1.8f),t*len));vs.Add(new Vector3(0,.16f*Mathf.Sin(t*1.8f)+w*.25f,t*len));vs.Add(new Vector3(w,.16f*Mathf.Sin(t*1.8f),t*len));}for(int k=0;k<8;k++)for(int side=0;side<2;side++){int a=k*3+side,b=a+3;ix.AddRange(new[]{a,b,b+1,a,b+1,a+1});}var mesh=new Mesh();mesh.SetVertices(vs);mesh.SetTriangles(ix,0);mesh.RecalculateNormals();g.AddComponent<MeshFilter>().sharedMesh=mesh;g.AddComponent<MeshRenderer>().sharedMaterial=leaf;}}
 if(kind==2){Part(root.transform,"Rear mounting gasket",Vector3.zero,new Vector3(.62f,.39f,.022f),dark);Part(root.transform,"Silver monitor case",new Vector3(0,0,.022f),new Vector3(.60f,.37f,.036f),silver);Part(root.transform,"Black bezel",new Vector3(0,0,.044f),new Vector3(.565f,.335f,.014f),dark);var screen=GameObject.CreatePrimitive(PrimitiveType.Quad);Object.DestroyImmediate(screen.GetComponent<Collider>());screen.name="Earth display";screen.transform.SetParent(root.transform,false);screen.transform.localPosition=new Vector3(0,0,.053f);screen.transform.localRotation=Quaternion.Euler(0,180,0);screen.transform.localScale=new Vector3(.53f,.298f,1);screen.GetComponent<Renderer>().sharedMaterial=earth;Part(root.transform,"Status lamp",new Vector3(.24f,-.163f,.056f),new Vector3(.025f,.004f,.004f),glow);}
 var box=root.AddComponent<BoxCollider>();box.center=kind==2?new Vector3(0,0,.025f):new Vector3(0,.18f,0);box.size=kind==2?new Vector3(.62f,.39f,.07f):new Vector3(.24f,.36f,.24f);return root;}
 static bool Polygon(float x,float y,Vector2[] p){bool inside=false;for(int i=0,j=p.Length-1;i<p.Length;j=i++){if((p[i].y>y)!=(p[j].y>y)&&x<(p[j].x-p[i].x)*(y-p[i].y)/(p[j].y-p[i].y)+p[i].x)inside=!inside;}return inside;}
 static Vector2[] Poly(params float[] a){var p=new Vector2[a.Length/2];for(int i=0;i<p.Length;i++)p[i]=new Vector2(a[i*2],a[i*2+1]);return p;}
 static Texture2D EarthTexture(){var t=new Texture2D(1024,576,TextureFormat.RGB24,true);t.name="Original procedural Earth with continents clouds atmosphere";var shapes=new[]{Poly(-17,36,4,37,35,30,50,11,42,-12,30,-35,18,-34,10,-5,-17,15),Poly(-10,36,-10,58,15,72,44,65,55,72,100,73,170,60,142,35,120,20,105,2,75,8,55,27,28,42),Poly(-165,65,-130,72,-110,60,-55,52,-80,24,-99,16,-120,32,-150,59),Poly(-81,12,-50,0,-35,-8,-48,-25,-68,-56,-76,-20),Poly(112,-12,140,-10,154,-28,135,-40,114,-34),Poly(-53,60,-20,82,-46,84,-65,72)};
 for(int y=0;y<t.height;y++)for(int x=0;x<t.width;x++){float sx=(x-t.width*.5f)/(t.height*.43f),sy=(y-t.height*.5f)/(t.height*.43f),rr=sx*sx+sy*sy;Color c=new Color(.008f,.018f,.035f);if(rr<=1){float z=Mathf.Sqrt(1-rr),lat=Mathf.Asin(sy)*Mathf.Rad2Deg,lon=Mathf.Atan2(sx,z)*Mathf.Rad2Deg+18;bool land=false;foreach(var poly in shapes)land|=Polygon(lon+(Mathf.PerlinNoise(lon*.35f+60,lat*.35f+60)-.5f)*2,lat+(Mathf.PerlinNoise(lon*.25f+90,lat*.25f+90)-.5f)*1.2f,poly);float noise=Mathf.PerlinNoise(lon*.07f+40,lat*.09f+40);c=land?Color.Lerp(new Color(.14f,.29f,.13f),new Color(.52f,.43f,.24f),noise):Color.Lerp(new Color(.018f,.075f,.23f),new Color(.035f,.26f,.44f),noise);if(Mathf.Abs(lat)>70)c=Color.Lerp(c,Color.white,(Mathf.Abs(lat)-70)/20);float clouds=Mathf.SmoothStep(0,1,Mathf.InverseLerp(.54f,.78f,Mathf.PerlinNoise(lon*.085f+10,lat*.11f+10)));c=Color.Lerp(c,Color.white,clouds*.8f);float light=Mathf.Clamp01(z*.7f-sx*.45f+.25f);c*=.22f+.78f*light;c=Color.Lerp(c,new Color(.18f,.53f,.9f),Mathf.Pow(1-z,4)*.65f);}else if(rr<1.08)c=Color.Lerp(new Color(.11f,.38f,.64f),c,(rr-1)/.08f);t.SetPixel(x,y,c);}t.Apply(true);return t;}
}
}
